from collections import deque
import threading

class ConcurrentQueue:
    def __init__(self):
        self.q = deque()
        self.lock = threading.Lock()

    def put(self, item):
        with self.lock:
            self.q.append(item)

    def get(self):
        with self.lock:
            if len(self.q) > 0:
                return self.q.popleft()
            return None
