import weakref
from collections import defaultdict


class WeakEventBus:
    """事件分发器，使用弱引用存储订阅者，避免阻止 GC。"""

    def __init__(self) -> None:
        # event_name -> list of (weakref.ref, func)
        #   bound method: (ref(obj), obj_method.__func__)
        #   普通可调用对象: (ref(obj), obj)  # 调用时 ref()()
        self._subscribers: dict[str, list[tuple[weakref.ref, object]]] = defaultdict(list)

    def subscribe(self, event_name: str, callback) -> None:
        """注册回调；仅保留弱引用，对象被 GC 后自动失效。"""
        if hasattr(callback, "__self__") and hasattr(callback, "__func__"):
            # bound method → 弱引用其所属对象
            obj = callback.__self__
            func = callback.__func__
            try:
                ref = weakref.ref(obj)
            except TypeError:
                return
            self._subscribers[event_name].append((ref, func))
        else:
            # 普通函数 / lambda / 类实例等
            # 普通函数不支持弱引用，直接跳过
            try:
                ref = weakref.ref(callback)
            except TypeError:
                return
            self._subscribers[event_name].append((ref, callback))

    def emit(self, event_name: str, *args, **kwargs) -> None:
        """分发事件，自动清理已失效的弱引用。"""
        subs = self._subscribers.get(event_name)
        if not subs:
            return

        alive = []
        for ref, func in subs:
            obj = ref()
            if obj is None:
                continue  # 对象已被 GC，跳过
            if hasattr(func, "__self__") or func is not obj:
                # bound method 场景：func 是底层函数，obj 是所属对象
                func(obj, *args, **kwargs)
            else:
                # 普通可调用对象
                obj(*args, **kwargs)
            alive.append((ref, func))

        self._subscribers[event_name] = alive
