class SagaExecutor:
    """A robust distributed-transaction Saga orchestrator.

    Steps are registered in order; actions run sequentially.
    If any action raises, all previously completed steps are
    compensated in strict reverse order (best-effort).
    """

    def __init__(self):
        self._steps: list[dict] = []

    def add_step(self, action, compensate) -> None:
        """Register a step with its forward action and compensation function."""
        if not callable(action):
            raise TypeError("action must be callable")
        if not callable(compensate):
            raise TypeError("compensate must be callable")
        self._steps.append({"action": action, "compensate": compensate})

    def execute(self) -> dict:
        """Run all steps in order; on failure, compensate in reverse.

        Returns:
            {'success': True,  'error': None}
            {'success': False, 'error': <Exception>, 'rollback_errors': [...]}
        """
        completed: list[dict] = []

        for step in self._steps:
            try:
                step["action"]()
                completed.append(step)
            except Exception as exc:
                # Strict reverse-order compensation (best-effort)
                rollback_errors: list[Exception] = []
                for comp_step in reversed(completed):
                    try:
                        comp_step["compensate"]()
                    except Exception as comp_exc:
                        rollback_errors.append(comp_exc)

                result: dict = {"success": False, "error": exc}
                if rollback_errors:
                    result["rollback_errors"] = rollback_errors
                return result

        return {"success": True, "error": None}

    def reset(self) -> None:
        """Clear all registered steps so the executor can be reused."""
        self._steps.clear()

    @property
    def step_count(self) -> int:
        return len(self._steps)
